import assert from 'node:assert/strict'
import { after, before, test } from 'node:test'
import { mkdir, mkdtemp, rm } from 'node:fs/promises'
import { request } from 'node:http'
import { tmpdir } from 'node:os'
import { join } from 'node:path'

import { startLocalApi } from '../index.js'
import { SAVE_DIR, createSave, save } from '../engine/state.js'

let home = ''
let server = null
let base = ''
let workspace = ''

/**
 * `fetch` is undici, and undici needs WebAssembly for llhttp. The device runs
 * --jitless, so the test client must use node:http too — that is also what the
 * app-side HTTP stack is talking to.
 */
function call(method, path, body) {
  return new Promise((resolve, reject) => {
    const payload = body === undefined ? '' : JSON.stringify(body)
    const req = request(`${base}${path}`, {
      method,
      headers: body === undefined
        ? {}
        : { 'content-type': 'application/json', 'content-length': Buffer.byteLength(payload) }
    }, (response) => {
      const chunks = []
      response.on('data', (chunk) => chunks.push(chunk))
      response.on('end', () => {
        try {
          resolve({
            status: response.statusCode,
            json: JSON.parse(Buffer.concat(chunks).toString('utf8'))
          })
        } catch (error) {
          reject(error)
        }
      })
    })
    req.on('error', reject)
    req.end(payload)
  })
}

function post(path, body) {
  return call('POST', path, body)
}

before(async () => {
  home = await mkdtemp(join(tmpdir(), 'sanguo-local-api-'))
  workspace = join(home, 'workspace')
  await mkdir(join(workspace, SAVE_DIR), { recursive: true })
  await save(workspace, createSave('api-test'))

  // The server reads HOME at request time; port 0 lets the OS pick a free one.
  process.env.HOME = home
  process.env.DSH_SANGUO_PORT = '0'
  server = startLocalApi()
  await new Promise((resolve) => server.once('listening', resolve))
  base = `http://127.0.0.1:${server.address().port}`
})

after(async () => {
  if (server !== null) {
    await new Promise((resolve) => server.close(resolve))
  }
  await rm(home, { recursive: true, force: true })
})

test('health answers without a workspace', async () => {
  const { status, json } = await call('GET', '/health')
  assert.equal(status, 200)
  assert.equal(json.ok, true)
})

test('state returns a rendered digest', async () => {
  const { status, json } = await post('/state', { workspace })
  assert.equal(status, 200)
  assert.equal(json.ok, true)
  assert.match(json.rendered, /刘备/)
  assert.ok(json.scene)
})

test('act commits one turn and returns the next scene', async () => {
  const { status, json } = await post('/act', {
    workspace,
    attribute: 'mei',
    difficulty: 40,
    intent: 'local api test'
  })
  assert.equal(status, 200)
  assert.equal(json.ok, true)
  assert.match(json.rendered, /【判定】/)
  assert.match(json.rendered, /【变化】/)
})

test('advance moves the clock', async () => {
  const { status, json } = await post('/advance', { workspace, turns: 1 })
  assert.equal(status, 200)
  assert.equal(json.ok, true)
  assert.match(json.rendered, /【时间】/)
})

test('a workspace outside HOME is rejected', async () => {
  const { status, json } = await post('/state', { workspace: '/etc' })
  assert.equal(status, 400)
  assert.equal(json.ok, false)
  assert.match(json.error, /workspace must be under/)
})
